/**
 * Condor Documentation - Client-side Mermaid Diagram Initializer
 * Automatically detects Mermaid code blocks generated by Doxygen and renders
 * interactive SVG flowcharts, sequence diagrams, class diagrams, etc.
 */
(function() {
    'use strict';

    function isDarkMode() {
        return document.documentElement.classList.contains('dark-mode') ||
               !document.documentElement.classList.contains('light-mode');
    }

    function getMermaidThemeConfig(dark) {
        return {
            startOnLoad: false,
            theme: dark ? 'dark' : 'default',
            themeVariables: dark ? {
                darkMode: true,
                background: '#002b36',
                mainBkg: '#073642',
                nodeBorder: '#2aa198',
                clusterBkg: '#002b36',
                clusterBorder: '#586e75',
                defaultLinkColor: '#268bd2',
                titleColor: '#93a1a1',
                edgeLabelBackground: '#073642',
                actorBorder: '#2aa198',
                actorBkg: '#073642',
                actorTextColor: '#839496',
                actorLineColor: '#586e75',
                signalColor: '#839496',
                signalTextColor: '#839496',
                labelBoxBkgColor: '#073642',
                labelBoxBorderColor: '#2aa198',
                labelTextColor: '#839496',
                loopTextColor: '#839496',
                noteBorderColor: '#b58900',
                noteBkgColor: '#073642',
                noteTextColor: '#93a1a1',
                activationBorderColor: '#2aa198',
                activationBkgColor: '#073642',
                sequenceNumberColor: '#002b36',
                classText: '#839496'
            } : {
                darkMode: false,
                background: '#fdf6e3',
                mainBkg: '#eee8d5',
                nodeBorder: '#2aa198',
                clusterBkg: '#fdf6e3',
                clusterBorder: '#93a1a1',
                defaultLinkColor: '#268bd2',
                titleColor: '#586e75',
                edgeLabelBackground: '#eee8d5',
                actorBorder: '#2aa198',
                actorBkg: '#eee8d5',
                actorTextColor: '#657b83',
                actorLineColor: '#93a1a1',
                signalColor: '#657b83',
                signalTextColor: '#657b83',
                labelBoxBkgColor: '#eee8d5',
                labelBoxBorderColor: '#2aa198',
                labelTextColor: '#657b83',
                loopTextColor: '#657b83',
                noteBorderColor: '#b58900',
                noteBkgColor: '#eee8d5',
                noteTextColor: '#586e75',
                activationBorderColor: '#2aa198',
                activationBkgColor: '#eee8d5',
                sequenceNumberColor: '#fdf6e3',
                classText: '#657b83'
            },
            securityLevel: 'loose',
            flowchart: {
                useMaxWidth: true,
                htmlLabels: true,
                curve: 'basis'
            },
            sequence: {
                useMaxWidth: true,
                showSequenceNumbers: false
            }
        };
    }

    var mermaidPattern = /^\s*(flowchart|sequenceDiagram|classDiagram|stateDiagram|stateDiagram-v2|erDiagram|gantt|pie|gitGraph|journey|mindmap|timeline|quadrantChart|xychart|graph\s+(?:TB|BT|RL|LR|TD))\b/;

    function extractCode(element) {
        var lines = element.querySelectorAll('.line');
        if (lines.length > 0) {
            var parts = [];
            lines.forEach(function(l) { parts.push(l.textContent); });
            return parts.join('\n').trim();
        }
        return element.textContent.trim();
    }

    function renderAllDiagrams() {
        if (typeof mermaid === 'undefined') {
            console.warn('[Condor Docs] Mermaid library not loaded.');
            return;
        }

        var dark = isDarkMode();
        mermaid.initialize(getMermaidThemeConfig(dark));

        // Discover fragments that contain Mermaid definitions
        var fragments = document.querySelectorAll('div.fragment');
        var targets = [];

        fragments.forEach(function(fragment) {
            var code = extractCode(fragment);
            if (mermaidPattern.test(code)) {
                var container = document.createElement('div');
                container.className = 'mermaid-diagram-container';
                container.style.textAlign = 'center';
                container.style.margin = '1.8em auto';
                container.style.maxWidth = '100%';
                container.style.overflowX = 'auto';
                container.style.padding = '1.2em';
                container.style.borderRadius = '8px';
                container.style.boxShadow = '0 2px 8px rgba(0,0,0,0.15)';
                container.style.backgroundColor = dark ? '#002b36' : '#fdf6e3';
                container.style.border = dark ? '1px solid #073642' : '1px solid #eee8d5';

                var pre = document.createElement('pre');
                pre.className = 'mermaid';
                pre.textContent = code;
                pre.setAttribute('data-mermaid-src', code);

                container.appendChild(pre);
                fragment.parentNode.replaceChild(container, fragment);
                targets.push(pre);
            }
        });

        if (targets.length > 0) {
            try {
                if (typeof mermaid.run === 'function') {
                    mermaid.run({ nodes: targets });
                } else if (typeof mermaid.init === 'function') {
                    mermaid.init(undefined, targets);
                }
            } catch (err) {
                console.error('[Condor Docs] Mermaid rendering error:', err);
            }
        }
    }

    function reRenderTheme(dark) {
        if (typeof mermaid === 'undefined') return;

        mermaid.initialize(getMermaidThemeConfig(dark));
        var containers = document.querySelectorAll('.mermaid-diagram-container');

        containers.forEach(function(container) {
            container.style.backgroundColor = dark ? '#002b36' : '#fdf6e3';
            container.style.border = dark ? '1px solid #073642' : '1px solid #eee8d5';

            var target = container.querySelector('.mermaid');
            if (target) {
                var rawCode = target.getAttribute('data-mermaid-src');
                if (rawCode) {
                    target.removeAttribute('data-processed');
                    target.innerHTML = '';
                    target.textContent = rawCode;
                }
            }
        });

        var preNodes = document.querySelectorAll('.mermaid-diagram-container .mermaid');
        if (preNodes.length > 0) {
            try {
                if (typeof mermaid.run === 'function') {
                    mermaid.run({ nodes: Array.from(preNodes) });
                } else if (typeof mermaid.init === 'function') {
                    mermaid.init(undefined, preNodes);
                }
            } catch (e) {
                console.warn('[Condor Docs] Mermaid theme refresh error:', e);
            }
        }
    }

    // Run on initial page load
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', renderAllDiagrams);
    } else {
        renderAllDiagrams();
    }

    // Watch for dark mode changes (from Doxygen-Awesome toggle)
    var wasDark = isDarkMode();
    var observer = new MutationObserver(function() {
        var nowDark = isDarkMode();
        if (nowDark !== wasDark) {
            wasDark = nowDark;
            reRenderTheme(nowDark);
        }
    });

    observer.observe(document.documentElement, {
        attributes: true,
        attributeFilter: ['class']
    });

})();
